import{z as l,x as A,o as i,c as B,q as E,j as t,D as e,d as n,s as r,S as o}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"IS–LM 作为会计","description":"","frontmatter":{"title":"IS–LM 作为会计","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/is-lm.md","filePath":"econ/is-lm.md","lastUpdated":1791413859000}'),p={name:"econ/is-lm.md"};function d(I,a,c,M,S,m){const s=A("Mermaid");return i(),B("div",null,[a[2]||(a[2]=E('<h1 id="is–lm-作为会计" tabindex="-1">IS–LM 作为会计 <a class="header-anchor" href="#is–lm-作为会计" aria-label="Permalink to &quot;IS–LM 作为会计&quot;">​</a></h1><div class="epigraph"><p>IS 把商品市场的均衡画成一条 $Y$–$i$ 轨迹；它不是对储蓄恒等式的否定，而是把事前计划写成与利率相容的一条线。</p><footer>—— Hicks, Mr. Keynes and the Classics, Econometrica 1937</footer></div><p><a href="/econ/natural-rate-u-star">上一课</a>（自然率假说）。在此之上，供给写成附加预期的菲利普斯：缺口动意外通胀。需求从哪来？<a href="/econ/saving-investment-id">储蓄–投资恒等</a>只保证事后 \\(S=I\\)（封闭）。本课的缺口是 Hicks 的那一步：把<strong>计划</strong>的 \\(I(i)\\) 与计划的 \\(S(Y)\\) 相等，再配上货币需求与给定的 \\(M\\)，得到短期 \\(Y\\) 与 \\(i\\)。后课欧拉会替换掉静态消费函数；本课禁止把 IS 当成跨期最优。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>事后恒等永远成立，不能决定 \\(Y\\)。Keynes 的有效需求要的是计划投资等于计划储蓄。Hicks（1937）把这句话画成 IS：在每个利率上，有一个使商品市场出清的产出。LM 是货币市场：\\(M/P=L(Y,i)\\)。两条线的交点是同时出清商品与货币的 \\((Y,i)\\)。价格 \\(P\\) 在本课先当作给定或缓动——粘性的微观基础是新凯恩斯，真实冲击对照是 RBC。</p><p>IS 不是「储蓄决定投资」的可贷资金图。利率在 LM 里由货币供求出，也可以被后课的利率规则直接钉住。本课用 Hicks 的原装置，是为了看清会计与均衡差在哪一层。</p><p><span class="marginnote">IS 上每一点都满足计划 \\(I=S\\)（或 \\(Y=C+I+G\\)）。移到 IS 之外则有非自愿存货，事后恒等靠存货投资去补。LM 之外则有货币的超额供求，靠 \\(i\\) 或 \\(Y\\) 调整。</span></p><p><span class="marginnote">IS/LM 的名字来自 Investment–Saving 与 Liquidity–Money：一条线管商品市场，一条线管货币市场。可以想象成两只手同时掰一根杠杆——商品市场要低利率才肯多投资，货币市场却在产出升高时抬高利率；两个市场同时不打架的位置，就是交点。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>封闭、价格给定。消费 \\(C=C(Y-T)\\)，投资 \\(I=I(i)\\)，政府 \\(G\\)。IS：</p> \\[Y=C(Y-T)+I(i)+G. \\]<p>LM：\\(M/P=L(Y,i)\\)。\\(M\\) 外生时，\\(P\\) 固定则 \\(i\\) 与 \\(Y\\) 沿 LM 同向。财政扩张移 IS，货币扩张移 LM。产出能否持久高于 \\(y^*\\)，要接菲利普斯：若 \\(P\\) 随后上升，LM 左移，回到自然率——这是 Mundell 与 Friedman 都能同意的长期垂直，不是 Hicks 原文的重点。</p>',12)),(i(),t(o,null,{default:e(()=>[r(s,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACC%5B%22%E4%BA%8B%E5%90%8E%20S%E2%89%A1I%22%5D%20--%3E%20IS%5B%22%E4%BA%8B%E5%89%8D%20I(i)%3DS(Y)%EF%BC%9AIS%22%5D%0A%20%20MD%5B%22M%2FP%3DL(Y%2Ci)%22%5D%20--%3E%20LM%5B%22LM%22%5D%0A%20%20IS%20--%3E%20EQ%5B%22%E4%BA%A4%E7%82%B9%20(Y%2Ci)%22%5D%0A%20%20LM%20--%3E%20EQ%0A%20%20EQ%20--%3E%20P%5B%22P%20%E5%8A%A8%E5%88%99%20LM%20%E7%A7%BB%E5%90%91%20y*%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p>流动性陷阱：在极低 \\(i\\)，货币与债券几乎完全替代，LM 水平，\\(M\\) 扩不动 \\(i\\)。这是后课零下限的祖先，Woodford 会改用利率规则语言。</p><p><span class="marginnote">数字实例：取 \\(C=0.6Y\\)、\\(I=100-10i\\)、\\(G=200\\)，代入 \\(Y=C+I+G\\) 解出 IS：\\(Y=750-25i\\)。利率每降 1 个点，出清产出多 25——「IS 向下倾斜」在这一次性系数 25 上看得见。消费倾向越高、投资对利率越敏感，这条线越平。</span></p><h3 id="为什么叫「作为会计」" tabindex="-1">为什么叫「作为会计」 <a class="header-anchor" href="#为什么叫「作为会计」" aria-label="Permalink to &quot;为什么叫「作为会计」&quot;">​</a></h3><p>IS 把支出恒等里的 \\(C,I,G\\) 写成行为，但仍是流量账户的平衡，不是生产函数。LM 把<a href="/econ/money-as-medium">货币层次</a>里的 \\(M\\) 写成存量需求。两者都不是增长核算，也不含资本运动定律——索洛在 \\(y^*\\) 上走，IS–LM 谈的是对 \\(y^*\\) 的偏离。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(i\\) 上升抑制计划投资，要维持商品出清必须更低的 \\(Y\\)（储蓄更少）——IS 向下倾斜。\\(Y\\) 上升提高交易性货币需求，给定 \\(M/P\\) 必须更高的 \\(i\\)——LM 向上倾斜。交点的比较静态是 Hicks 对《通论》的翻译：同一套符号，既可以读凯恩斯的数量调节，也可以读古典的利率调节，取决于哪条线更陡、价格动得有多快。</p><p>长期若 \\(P\\) 灵活且预期正确，交点的 \\(Y\\) 被钉在 \\(y^*\\)，货币只定 \\(P\\) 与名义 \\(i\\) 的费雪部分。短替换来自 \\(P\\) 粘住或 \\(\\pi^e\\) 滞后，已经在菲利普斯课写过。</p><p>流动性陷阱：\\(i\\) 不能再降时 LM 变平，货币扩张不再降 \\(i\\)——零下限课再写。古典极端 LM 垂直时财政完全挤出；Keynes 极端 LM 水平时货币无效。这些是斜率特例。Hicks 自己后来对教学图有保留。本栏仍用它，因为 NK 的动态 IS 是它的跨期替换。</p>',8)),(i(),t(o,null,{default:e(()=>[r(s,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20GF%5B%22%E8%B4%A2%E6%94%BF%E6%89%A9%E5%BC%A0%3A%20IS%20%E5%8F%B3%E7%A7%BB%22%5D%20--%3E%20YUP%5B%22Y%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20YUP%20--%3E%20MDUP%5B%22%E4%BA%A4%E6%98%93%E6%80%A7%E8%B4%A7%E5%B8%81%E9%9C%80%E6%B1%82%E4%B8%8A%E5%8D%87%22%5D%0A%20%20MDUP%20--%3E%20IUP%5B%22%E5%88%A9%E7%8E%87%E8%A2%AB%E6%8A%AC%3A%20%E6%8C%A4%E5%87%BA%E7%A7%81%E4%BA%BA%E6%8A%95%E8%B5%84%22%5D%0A%20%20GM%5B%22%E8%B4%A7%E5%B8%81%E6%89%A9%E5%BC%A0%3A%20LM%20%E5%8F%B3%E7%A7%BB%22%5D%20--%3E%20IDOWN%5B%22%E5%88%A9%E7%8E%87%E4%B8%8B%E9%99%8D%22%5D%0A%20%20IDOWN%20--%3E%20INVUP%5B%22%E6%8A%95%E8%B5%84%E8%A2%AB%E5%88%BA%E6%BF%80%22%5D%0A%20%20FLAT%5B%22LM%20%E6%B0%B4%E5%B9%B3%3A%20%E6%B5%81%E5%8A%A8%E6%80%A7%E9%99%B7%E9%98%B1%22%5D%20--%3E%20NOPE%5B%22%E8%B4%A7%E5%B8%81%E6%89%A9%E4%B8%8D%E5%8A%A8%20i%22%5D%0A%20%20VERT%5B%22LM%20%E5%9E%82%E7%9B%B4%22%5D%20--%3E%20NULLG%5B%22%E8%B4%A2%E6%94%BF%E5%AE%8C%E5%85%A8%E6%8C%A4%E5%87%BA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<p><span class="marginnote">常见误区：以为政府花钱一定等量变成产出。实际上 \\(G\\) 上升推高 \\(Y\\)，交易性货币需求跟着涨，给定 \\(M/P\\) 利率被抬上去，私人投资被挤掉一块——这就是「挤出」。LM 越陡挤得越狠，垂直时财政一分钱净效果都没有。</span></p><p><span class="marginnote">Walras 定律意味着债券市场也清。本课不把债券再画一条，以免三重计算。IS 上每一点是商品均衡，不是恒等。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>静态 \\(C(Y)\\) 切断欧拉方程，利率对消费的跨期替代被藏进含糊的 \\(I(i)\\)。开放经济的 IS 要加净出口与汇率，是蒙代尔–弗莱明。本课也不写限价簿上的利率；宏观 \\(i\\) 是政策或债券的一个标量。卢卡斯会问：政策一变，\\(C_Y\\)、\\(L_i\\) 还在不在。</p><p>后课默认：说到 IS–LM，指的是事前流量与货币存量的同时均衡，不是 SNA 恒等本身。下一课用消费欧拉替换 \\(C(Y)\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>事后 \\(S=I\\) 是恒等；IS 是计划量的商品均衡轨迹。</li><li>LM 是给定 \\(M/P\\) 的货币均衡；交点定短期 \\((Y,i)\\)。</li><li>\\(P\\) 灵活时交点回到 \\(y^*\\)，与货币中性对齐。</li><li>斜率特例给出挤出与流动性陷阱。</li><li>静态消费函数是缺口；欧拉与利率规则是后课。</li><li>出处：Hicks, Econometrica 1937。</li></ul>',7))])}const h=l(p,[["render",d]]);export{L as __pageData,h as default};
